  /**
   * 1D Model generator method
   * @param model_opt_ptree are the options which model will be built and
   * returned
   */
  std::shared_ptr<Model1D>
  generate1DModel(const boost::property_tree::ptree &model_opt_ptree,
                  const PndLmdAngularData &data) const;

  /**
   * 2D Model generator method
   * @param model_opt_ptree are the options which model will be built and
   * returned
   */
  std::shared_ptr<Model2D>
  generate2DModel(const boost::property_tree::ptree &model_opt_ptree,
                  const PndLmdAngularData &data) const;

public:
