std::shared_ptr<Model1D> PndLmdModelFactory::generate1DVertexModel(
    const boost::property_tree::ptree &model_opt_ptree) const {
  std::shared_ptr<Model1D> vertex_model;

  LumiFit::ModelType model_type(LumiFit::StringToModelType.at(
      model_opt_ptree.get<std::string>("model_type")));

  if (model_type == LumiFit::UNIFORM) {
    vertex_model.reset(new DoubleGaussianModel1D("vertex_double_gaussian_1d"));
  } else if (model_type == LumiFit::GAUSSIAN) {
    vertex_model.reset(new GaussianModel1D("vertex_gaussian_1d"));
  } else {
    std::cout
        << "Unknown vertex model! Only uniform and gaussian model is allowed."
        << std::endl;
  }

  return vertex_model;
}

std::shared_ptr<Model> PndLmdModelFactory::generateModel(
    const boost::property_tree::ptree &model_opt_ptree,
    const PndLmdAngularData &data) const {
  std::shared_ptr<Model> current_model;

  std::cout << "Generating model ... " << std::endl;

  unsigned int fit_dimension =
      model_opt_ptree.get<unsigned int>("fit_dimension");
  if (fit_dimension == 1) {
    current_model = generate1DModel(model_opt_ptree, data);
  } else if (fit_dimension == 2) {
    current_model = generate2DModel(model_opt_ptree, data);
  } else {
    std::cout << "WARNING: Requesting a model of dimension " << fit_dimension
              << " which is NOT available! Returning NULL pointer."
              << std::endl;
  }
  return current_model;
}

void PndLmdDivergenceSmearingModel2D::optimizeNumericalIntegration(
    const std::vector<std::vector<std::pair<int, int>>> &xy_pairs_lists) {
  unsigned int nthreads =
      PndLmdRuntimeConfiguration::Instance().getNumberOfThreads();

  /*std::shared_ptr<SimpleIntegralStrategy2D> integral_strategy(
      new SimpleIntegralStrategy2D());
  divergence_model->setIntegralStrategy(integral_strategy);

  unsigned int calls(7);

  integral_strategy->setUsedEvaluationGridConstant(calls);*/

  mydouble div_bin_size_x = data_dim_x.bin_size;
  mydouble div_bin_size_y = data_dim_y.bin_size;

  std::shared_ptr<IntegralStrategyGSL2D> integral_strategy(
      new IntegralStrategyGSL2D());
  divergence_model->setIntegralStrategy(integral_strategy);

  unsigned int calls(2);
  std::vector<std::vector<DataStructs::DimensionRange>> int_ranges(nthreads);
  std::vector<DataStructs::DimensionRange> int_range(2);
  std::vector<std::future<unsigned int>> future_list;
  std::vector<std::thread> thread_list;

  std::mt19937 gen;
  for (unsigned int i = 0; i < nthreads; i++) {
    if (xy_pairs_lists[i].size() > 0) {
      std::uniform_int_distribution<unsigned int> random_index(
          0, xy_pairs_lists[i].size() - 1);
      unsigned int index = random_index(gen);

      int_range[0].range_low =
          (xy_pairs_lists[i][index].first - 0.5) * div_bin_size_x;
      int_range[0].range_high =
          (xy_pairs_lists[i][index].first + 0.5) * div_bin_size_x;

      int_range[1].range_low =
          (xy_pairs_lists[i][index].second - 0.5) * div_bin_size_y;
      int_range[1].range_high =
          (xy_pairs_lists[i][index].second + 0.5) * div_bin_size_y;

      int_ranges[i] = int_range;

      std::packaged_task<unsigned int()> task(
          std::bind(&IntegralStrategyGSL2D::determineOptimalCallNumber,
                    integral_strategy.get(), divergence_model.get(),
                    std::cref(int_ranges[i]), integral_precision));
      future_list.push_back(task.get_future());
      thread_list.push_back(std::thread(std::move(task)));
    }
  }
  // wait for futures and compute maximum number of calls

  for (auto &future : future_list) {
    unsigned int temp_calls = future.get();
    if (temp_calls > calls)
      calls = temp_calls;
  }

  // join all threads
  for (auto &thread : thread_list) {
    if (thread.joinable())
      thread.join();
  }

  // std::cout << "using start call: " << calls << std::endl;
  integral_strategy->setStartNumberOfFunctionEvaluations(calls);
}

